CREATE TABLE IF NOT EXISTS sources (source_id VARCHAR PRIMARY KEY, url VARCHAR NOT NULL, license VARCHAR NOT NULL, attribution VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS ingestion_runs (run_id VARCHAR PRIMARY KEY, source_id VARCHAR NOT NULL, season VARCHAR, started_at TIMESTAMP NOT NULL, finished_at TIMESTAMP, status VARCHAR NOT NULL, message VARCHAR);
CREATE TABLE IF NOT EXISTS datasets (dataset_id VARCHAR PRIMARY KEY, source_id VARCHAR NOT NULL, url VARCHAR NOT NULL, revision VARCHAR NOT NULL, retrieved_at TIMESTAMP NOT NULL, sha256 VARCHAR NOT NULL, raw_path VARCHAR NOT NULL, row_count BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS seasons (season VARCHAR PRIMARY KEY, end_year INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS teams (team_id VARCHAR PRIMARY KEY, provider VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS team_identities (team_id VARCHAR NOT NULL, season VARCHAR NOT NULL, abbreviation VARCHAR NOT NULL, name VARCHAR NOT NULL, PRIMARY KEY(team_id, season));
CREATE TABLE IF NOT EXISTS players (player_id VARCHAR PRIMARY KEY, name VARCHAR NOT NULL, search_name VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS player_identifiers (provider VARCHAR NOT NULL, provider_id VARCHAR NOT NULL, player_id VARCHAR NOT NULL, PRIMARY KEY(provider, provider_id));
CREATE TABLE IF NOT EXISTS games (game_id VARCHAR PRIMARY KEY, season VARCHAR NOT NULL, season_type INTEGER NOT NULL, game_date DATE NOT NULL, home_team_id VARCHAR NOT NULL, away_team_id VARCHAR NOT NULL, home_score INTEGER, away_score INTEGER, completed BOOLEAN NOT NULL, dataset_id VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS player_box_scores (game_id VARCHAR NOT NULL, player_id VARCHAR NOT NULL, team_id VARCHAR NOT NULL, minutes DOUBLE, fgm INTEGER, fga INTEGER, fg3m INTEGER, fg3a INTEGER, ftm INTEGER, fta INTEGER, points INTEGER, assists INTEGER, turnovers INTEGER, rebounds INTEGER, did_not_play BOOLEAN, dataset_id VARCHAR NOT NULL, PRIMARY KEY(game_id, player_id));
CREATE TABLE IF NOT EXISTS team_box_scores (game_id VARCHAR NOT NULL, team_id VARCHAR NOT NULL, points INTEGER, fgm INTEGER, fga INTEGER, fg3m INTEGER, fg3a INTEGER, ftm INTEGER, fta INTEGER, assists INTEGER, turnovers INTEGER, dataset_id VARCHAR NOT NULL, PRIMARY KEY(game_id, team_id));
CREATE TABLE IF NOT EXISTS pbp_events (game_id VARCHAR NOT NULL, event_id VARCHAR NOT NULL, event_order INTEGER NOT NULL, period INTEGER NOT NULL, clock VARCHAR, event_type VARCHAR, description VARCHAR, team_id VARCHAR, player_id VARCHAR, home_score INTEGER, away_score INTEGER, dataset_id VARCHAR NOT NULL, PRIMARY KEY(game_id, event_id));
CREATE TABLE IF NOT EXISTS shot_attempts (game_id VARCHAR NOT NULL, event_id VARCHAR NOT NULL, player_id VARCHAR, team_id VARCHAR, points_attempted INTEGER, made BOOLEAN, x DOUBLE, y DOUBLE, coordinate_system VARCHAR NOT NULL, observation_type VARCHAR NOT NULL, dataset_id VARCHAR NOT NULL, PRIMARY KEY(game_id, event_id));
CREATE TABLE IF NOT EXISTS substitutions (game_id VARCHAR NOT NULL, event_id VARCHAR NOT NULL, description VARCHAR, dataset_id VARCHAR NOT NULL, PRIMARY KEY(game_id, event_id));
CREATE TABLE IF NOT EXISTS lineups (lineup_id VARCHAR PRIMARY KEY, game_id VARCHAR NOT NULL, team_id VARCHAR NOT NULL, start_event_id VARCHAR NOT NULL, end_event_id VARCHAR NOT NULL, observation_type VARCHAR NOT NULL, dataset_id VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS lineup_players (lineup_id VARCHAR NOT NULL, player_id VARCHAR NOT NULL, PRIMARY KEY(lineup_id, player_id));
CREATE TABLE IF NOT EXISTS matchup_observations (observation_id VARCHAR PRIMARY KEY, game_id VARCHAR NOT NULL, offensive_player_id VARCHAR NOT NULL, defender_player_id VARCHAR, assignment_type VARCHAR NOT NULL, observation_type VARCHAR NOT NULL, fgm INTEGER, fga INTEGER, dataset_id VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS contracts (contract_id VARCHAR PRIMARY KEY, player_id VARCHAR NOT NULL, signed_date DATE, guaranteed_usd DOUBLE, dataset_id VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS salaries (contract_id VARCHAR NOT NULL, season VARCHAR NOT NULL, team_id VARCHAR NOT NULL, salary_usd DOUBLE, cap_hit_usd DOUBLE, option_type VARCHAR, dataset_id VARCHAR NOT NULL, PRIMARY KEY(contract_id, season, team_id));
CREATE TABLE IF NOT EXISTS injuries (report_id VARCHAR PRIMARY KEY, player_id VARCHAR NOT NULL, team_id VARCHAR NOT NULL, reported_at TIMESTAMP NOT NULL, status VARCHAR, reason VARCHAR, dataset_id VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS possessions (possession_id VARCHAR PRIMARY KEY, game_id VARCHAR NOT NULL, period INTEGER NOT NULL, offense_team_id VARCHAR NOT NULL, start_event_id VARCHAR NOT NULL, end_event_id VARCHAR NOT NULL, start_order INTEGER NOT NULL, end_order INTEGER NOT NULL, points INTEGER NOT NULL, end_reason VARCHAR NOT NULL, reconstruction_version VARCHAR NOT NULL, dataset_id VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS possession_events (game_id VARCHAR NOT NULL, event_id VARCHAR NOT NULL, possession_id VARCHAR, attribution VARCHAR NOT NULL, PRIMARY KEY(game_id,event_id));
CREATE TABLE IF NOT EXISTS non_possession_points (game_id VARCHAR NOT NULL, event_id VARCHAR NOT NULL, team_id VARCHAR NOT NULL, points INTEGER NOT NULL, reason VARCHAR NOT NULL, PRIMARY KEY(game_id,event_id));
CREATE TABLE IF NOT EXISTS reconstruction_status (game_id VARCHAR PRIMARY KEY, season VARCHAR NOT NULL, version VARCHAR NOT NULL, possessions_status VARCHAR NOT NULL, lineups_status VARCHAR NOT NULL, resolved_team_periods INTEGER NOT NULL, expected_team_periods INTEGER NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS quality_exceptions (exception_id VARCHAR PRIMARY KEY, game_id VARCHAR, season VARCHAR NOT NULL, stage VARCHAR NOT NULL, severity VARCHAR NOT NULL, rule VARCHAR NOT NULL, detail VARCHAR NOT NULL, dataset_id VARCHAR, version VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS lineup_minute_checks (game_id VARCHAR NOT NULL, player_id VARCHAR NOT NULL, reconstructed_seconds DOUBLE NOT NULL, box_seconds DOUBLE, tolerance_seconds DOUBLE NOT NULL, passed BOOLEAN NOT NULL, PRIMARY KEY(game_id,player_id));
CREATE TABLE IF NOT EXISTS independent_team_totals (source_id VARCHAR NOT NULL, source_game_id VARCHAR NOT NULL, season VARCHAR NOT NULL, game_date DATE NOT NULL, team_id VARCHAR NOT NULL, opponent_team_id VARCHAR NOT NULL, home BOOLEAN NOT NULL, points INTEGER, fgm INTEGER, fga INTEGER, fg3m INTEGER, fg3a INTEGER, ftm INTEGER, fta INTEGER, assists INTEGER, turnovers INTEGER, dataset_id VARCHAR NOT NULL, PRIMARY KEY(source_id,source_game_id,team_id));
CREATE TABLE IF NOT EXISTS reconciliation_checks (game_id VARCHAR NOT NULL, team_id VARCHAR NOT NULL, reference_dataset_id VARCHAR NOT NULL, reference_game_id VARCHAR NOT NULL, metric VARCHAR NOT NULL, warehouse_value DOUBLE, reference_value DOUBLE, difference DOUBLE, passed BOOLEAN, PRIMARY KEY(game_id,team_id,reference_dataset_id,metric));
CREATE TABLE IF NOT EXISTS schedule_inventory (game_id VARCHAR PRIMARY KEY, season VARCHAR NOT NULL, game_date DATE NOT NULL, home_team_id VARCHAR NOT NULL, away_team_id VARCHAR NOT NULL, has_player_box BOOLEAN NOT NULL, has_team_box BOOLEAN NOT NULL, has_pbp BOOLEAN NOT NULL, validation_status VARCHAR NOT NULL, dataset_id VARCHAR NOT NULL);
CREATE TABLE IF NOT EXISTS pbp_reconciliation_checks (game_id VARCHAR NOT NULL, team_id VARCHAR NOT NULL, metric VARCHAR NOT NULL, observed DOUBLE, box_value DOUBLE, difference DOUBLE, passed BOOLEAN, status VARCHAR NOT NULL, unknown_events INTEGER NOT NULL, version VARCHAR NOT NULL, PRIMARY KEY(game_id,team_id,metric));
CREATE TABLE IF NOT EXISTS dataset_dependencies (dataset_id VARCHAR NOT NULL, parent_dataset_id VARCHAR NOT NULL, transformation VARCHAR NOT NULL, PRIMARY KEY(dataset_id,parent_dataset_id));
